(() => {const button=document.querySelector('[data-copy-citation]');if(!button)return;const citation=document.querySelector('[data-citation]').value,status=document.querySelector('[data-research-status]');button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(citation);status.textContent='Citation copied, including version and source link.'}catch{const field=document.querySelector('[data-citation]');field.hidden=false;field.focus();field.select();status.textContent='Select and copy the citation below.'}});document.querySelector('[data-print-note]').addEventListener('click',()=>window.print())})();
